export function clamp(number, min, max) {
  return Math.min(Math.max(number, min), max);
}

// ------------------------------------------------------------
// IMPLIED PROBABILITY
// ------------------------------------------------------------

export function impliedProbability(decimalOdds) {
  if (!decimalOdds || decimalOdds <= 1) {
    return 0;
  }

  return 1 / decimalOdds;
}

// ------------------------------------------------------------
// EXPECTED VALUE
// ------------------------------------------------------------

export function expectedValue(probability, decimalOdds) {
  if (!decimalOdds || decimalOdds <= 1) {
    return 0;
  }

  return probability * decimalOdds - 1;
}

// ------------------------------------------------------------
// VOLATILITY
// ------------------------------------------------------------

export function volatilityFromReturns(returns) {
  if (!returns || returns.length < 2) {
    return 0;
  }

  const mean =
    returns.reduce((sum, value) => sum + value, 0) /
    returns.length;

  const variance =
    returns.reduce(
      (sum, value) => sum + Math.pow(value - mean, 2),
      0
    ) /
    (returns.length - 1);

  return Math.sqrt(variance);
}

// ------------------------------------------------------------
// MAX DRAWDOWN
// ------------------------------------------------------------

export function maxDrawdown(equityCurve) {
  if (!equityCurve || equityCurve.length === 0) {
    return 0;
  }

  let peak = equityCurve[0];
  let largestDrawdown = 0;

  for (const value of equityCurve) {
    if (value > peak) {
      peak = value;
    }

    const drawdown = (peak - value) / peak;

    if (drawdown > largestDrawdown) {
      largestDrawdown = drawdown;
    }
  }

  return largestDrawdown;
}

// ------------------------------------------------------------
// SHARPE RATIO
// ------------------------------------------------------------

export function sharpeRatio(returns, riskFreeRate = 0) {
  if (!returns || returns.length < 2) {
    return 0;
  }

  const average =
    returns.reduce((sum, value) => sum + value, 0) /
    returns.length;

  const excessReturn = average - riskFreeRate;

  const volatility = volatilityFromReturns(returns);

  if (volatility === 0) {
    return 0;
  }

  return excessReturn / volatility;
}

// ------------------------------------------------------------
// SORTINO RATIO
// ------------------------------------------------------------

export function sortinoRatio(returns, targetReturn = 0) {
  if (!returns || returns.length < 2) {
    return 0;
  }

  const average =
    returns.reduce((sum, value) => sum + value, 0) /
    returns.length;

  const downsideReturns = returns.filter(
    (value) => value < targetReturn
  );

  if (downsideReturns.length === 0) {
    return average > targetReturn ? 999 : 0;
  }

  const downsideVariance =
    downsideReturns.reduce(
      (sum, value) =>
        sum + Math.pow(value - targetReturn, 2),
      0
    ) / downsideReturns.length;

  const downsideDeviation = Math.sqrt(downsideVariance);

  if (downsideDeviation === 0) {
    return 0;
  }

  return (average - targetReturn) / downsideDeviation;
}

// ------------------------------------------------------------
// FRACTIONAL KELLY
// ------------------------------------------------------------

export function fractionalKelly(
  probability,
  decimalOdds,
  fraction = 0.25
) {
  if (!decimalOdds || decimalOdds <= 1) {
    return 0;
  }

  const b = decimalOdds - 1;
  const q = 1 - probability;

  const kelly =
    (b * probability - q) / b;

  return Math.max(0, kelly * fraction);
}

// ------------------------------------------------------------
// MONTE CARLO SIMULATION
// ------------------------------------------------------------

export function monteCarlo({
  probability,
  winReturn,
  lossReturn,
  trials = 5000,
  bankroll = 1000,
}) {
  const finalValues = [];

  for (let trial = 0; trial < trials; trial++) {
    let value = bankroll;

    for (let i = 0; i < 100; i++) {
      const randomValue = Math.random();

      if (randomValue < probability) {
        value *= 1 + winReturn;
      } else {
        value *= 1 + lossReturn;
      }

      if (value <= 0) {
        value = 0;
        break;
      }
    }

    finalValues.push(value);
  }

  finalValues.sort((a, b) => a - b);

  const average =
    finalValues.reduce(
      (sum, value) => sum + value,
      0
    ) / finalValues.length;

  const median =
    finalValues[Math.floor(finalValues.length / 2)];

  const worstCase =
    finalValues[Math.floor(finalValues.length * 0.05)];

  const bestCase =
    finalValues[Math.floor(finalValues.length * 0.95)];

  return {
    average,
    median,
    worstCase,
    bestCase,
  };
}

// ------------------------------------------------------------
// COMPLETE SETUP ANALYSIS
// ------------------------------------------------------------

export function analyzeSetup(input) {
  const {
    probability,
    decimalOdds,
    maxLoss,
    riskBudget,
    volatility,
    confidence,
    modelAgreement,
  } = input;

  const probabilityDecimal =
    clamp(probability, 0, 100) / 100;

  const implied =
    impliedProbability(decimalOdds);

  const ev =
    expectedValue(
      probabilityDecimal,
      decimalOdds
    );

  const kelly =
    fractionalKelly(
      probabilityDecimal,
      decimalOdds,
      0.25
    );

  const safeConfidence =
    clamp(confidence, 0, 100);

  const safeAgreement =
    clamp(modelAgreement, 0, 100);

  const safeVolatility =
    Math.max(0, volatility);

  let score = 50;

  const reasons = [];

  // Expected value
  if (ev > 0) {
    score += 15;

    reasons.push(
      "Estimated probability produces positive expected value."
    );
  } else {
    score -= 25;

    reasons.push(
      "Estimated probability does not produce positive expected value."
    );
  }

  // Confidence
  if (safeConfidence >= 70) {
    score += 10;

    reasons.push(
      "Confidence level is relatively strong."
    );
  } else if (safeConfidence < 50) {
    score -= 12;

    reasons.push(
      "Confidence level is below the preferred threshold."
    );
  }

  // Model agreement
  if (safeAgreement >= 70) {
    score += 8;

    reasons.push(
      "The analytical models show strong agreement."
    );
  } else if (safeAgreement < 50) {
    score -= 10;

    reasons.push(
      "The analytical models show limited agreement."
    );
  }

  // Volatility
  if (safeVolatility > 8) {
    score -= 12;

    reasons.push(
      "Volatility is elevated."
    );
  } else {
    reasons.push(
      "Volatility is within the prototype's preferred range."
    );
  }

  // Risk budget
  if (maxLoss > riskBudget) {
    score -= 40;

    reasons.push(
      "Maximum potential loss exceeds the defined risk budget."
    );
  } else {
    reasons.push(
      "Maximum potential loss is within the defined risk budget."
    );
  }

  score = clamp(score, 0, 100);

  let label = "WATCH";

  if (
    maxLoss > riskBudget ||
    ev <= 0 ||
    safeConfidence < 45 ||
    safeAgreement < 45
  ) {
    label = "REJECTED";
  } else if (score >= 75) {
    label = "QUALIFIED";
  }

  return {
    score,
    label,
    expectedValue: ev,
    impliedProbability: implied,
    kellyFraction: kelly,
    reasons,
  };
}
